-- Migration 017: Runbook proof support
-- Adds proof column to compliance_completions for structured proof tracking.
-- Re-creates board_tasks table (dropped in 006) with linked_item_id for
-- follow-up tasks generated by the runbook drawer.

-- 1. Add proof jsonb column to compliance_completions
alter table compliance_completions
  add column if not exists proof jsonb;

-- 2. Re-create board_tasks for runbook follow-up items
create table if not exists board_tasks (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenants(id) on delete cascade,
  title text not null,
  due_date date,
  completed boolean not null default false,
  completed_at timestamptz,
  linked_item_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Add linked_item_id if the table already existed without it
alter table board_tasks
  add column if not exists linked_item_id text;

-- Constraint: proof kind must be one of the known values
alter table compliance_completions
  add constraint compliance_completions_proof_kind_check
  check (
    proof is null
    or proof->>'kind' in (
      'attachment', 'communication', 'filing', 'case', 'meeting', 'reason'
    )
  );
